public 
enum HttpError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case UrlParsing(message: String)
    
    case Request(message: String)
    
    case Serialize(message: String)
    
    case Unauthenticated(message: String)
    
    case PoisonedSession(message: String)
    
    case InvalidStatus(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension HttpError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHttpError: FfiConverterRustBuffer {
    typealias SwiftType = HttpError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HttpError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .UrlParsing(
            message: try FfiConverterString.read(from: &buf)
